::: {.cell}

```{.r .cell-code}
# Stap 1: stel parameters in
p <- 2e11    
d <- 1/120   

# Stap 2: stel het beginaantal B in
B <- p/d

# Stap 3: maak functie die B, p, en d gebruikt om de verandering uit te rekenen
verandering <- function (B, p, d){
  delta <- p - d*B
  return(delta)
}

# Stap 4: een test of de functie werkt
